from datetime import date
from decimal import Decimal, InvalidOperation
import calendar


MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
          'August', 'September', 'October', 'November', 'December']


def amount(value):
    try:
        return Decimal(str(value or '0').replace(',', '')).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError):
        return Decimal('0.00')


def backfill_installments_and_payments(apps, schema_editor):
    Loan = apps.get_model('Adworker', 'FormMkopo')
    Payment = apps.get_model('Adworker', 'Malipo')
    Installment = apps.get_model('Adworker', 'LoanInstallment')
    Allocation = apps.get_model('Adworker', 'PaymentAllocation')

    for loan in Loan.objects.all().iterator():
        try:
            year = int(loan.mwaka)
        except (TypeError, ValueError):
            year = 0
        if year < 1 or year > 9999:
            try:
                year = date.fromisoformat(str(loan.tarehe)[:10]).year
            except (TypeError, ValueError):
                continue
        try:
            day = int(loan.day)
        except (TypeError, ValueError):
            try:
                day = date.fromisoformat(str(loan.tarehe)[:10]).day
            except (TypeError, ValueError):
                day = 1

        previous_month = None
        for sequence in range(1, 13):
            name = str(getattr(loan, 'mwezi%s' % sequence, '') or '').strip().lower()
            month = next((index for index, month_name in enumerate(MONTHS, 1)
                          if month_name.lower() == name), None)
            scheduled = amount(getattr(loan, 'mw%s' % sequence, None))
            if month is None or scheduled <= 0:
                continue
            if previous_month is not None and month < previous_month:
                year += 1
            previous_month = month
            due_day = min(max(day, 1), calendar.monthrange(year, month)[1])
            Installment.objects.get_or_create(
                loan_id=loan.pk, sequence=sequence,
                defaults={'due_date': date(year, month, due_day), 'scheduled_amount': scheduled}
            )

    # Reconstruct old receipts chronologically, allocating each to the oldest
    # eligible unpaid installment for the same borrower and account.
    for payment in Payment.objects.filter(route='weka').exclude(info__in=['delete', 'deleted']).order_by('pk').iterator():
        remaining = amount(payment.loan_repay)
        if remaining <= 0:
            remaining = amount(payment.Total_pay)
        if remaining <= 0:
            continue
        loans = Loan.objects.filter(user=payment.user, Account_no=payment.Account_no)
        if payment.company:
            loans = loans.filter(company=payment.company)
        candidates = Installment.objects.filter(loan_id__in=loans.values('pk')).order_by('due_date', 'loan_id', 'sequence')
        for installment in candidates.iterator():
            already_paid = sum(Allocation.objects.filter(installment_id=installment.pk).values_list('amount', flat=True), Decimal('0.00'))
            outstanding = max(Decimal('0.00'), installment.scheduled_amount - already_paid)
            if outstanding <= 0:
                continue
            applied = min(remaining, outstanding)
            Allocation.objects.get_or_create(
                payment_id=payment.pk, installment_id=installment.pk,
                defaults={'amount': applied}
            )
            remaining -= applied
            if remaining <= 0:
                break


